import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String company = sc.next();
        int gold = sc.nextInt();
        int silver = sc.nextInt();
        int perGold = sc.nextInt();
        int perSilver = sc.nextInt();
        int base = gold * perGold + silver * perSilver;
        int bonus = base / 10;
        int grand = base + bonus;
        String tier;
        if(grand >= 100000) {
            tier = "PLATINUM";
        } else if(grand >= 25000) {
            tier = "GOLD";
        } else {
            tier = "SILVER";
        }
        System.out.println("Sponsor: " + company);
        System.out.println("Base amount: " + base);
        System.out.println("Bonus amount: " + bonus);
        System.out.println("Grand total: " + grand);
        System.out.println("Tier: " + tier);
    }
}

