import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long value = sc.nextLong();
        String unit = sc.next();
        long bytes;
        switch(unit) {
            case "KB":
                bytes = value * 1024L;
                break;
            case "MB":
                bytes = value * 1024L * 1024L;
                break;
            default:
                bytes = value * 1024L * 1024L * 1024L;
                break;
        }
        System.out.println("Value: " + value);
        System.out.println("Unit: " + unit);
        System.out.println("Bytes: " + bytes);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long a = sc.nextLong();
        long b = sc.nextLong();
        System.out.println("Value A: " + a);
        System.out.println("Value B: " + b);
        boolean over = (a > 0 && b > 0 && a > Long.MAX_VALUE - b) || (a < 0 && b < 0 && a < Long.MIN_VALUE - b);
        if(over) {
            System.out.println("Safe sum: overflow");
            System.out.println("Status: OVERFLOW");
            System.out.println("Max long: " + Long.MAX_VALUE);
        } else {
            System.out.println("Safe sum: " + (a + b));
            System.out.println("Status: OK");
        }
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String name = sc.nextLine().trim();
        int age = sc.nextInt();
        String tier = sc.next();
        int base = sc.nextInt();
        int pct;
        switch(tier) {
            case "V":
                pct = 20;
                break;
            case "G":
                pct = 10;
                break;
            default:
                pct = 0;
                break;
        }
        int discount = base * pct / 100;
        int finalPrice = base - discount;
        char code = (char) ('A' + finalPrice % 26);
        System.out.println("Attendee: " + name);
        System.out.println("Age: " + age);
        System.out.println("Tier: " + tier);
        System.out.println("Discount: " + discount);
        System.out.println("Final price: " + finalPrice);
        System.out.println("Access code: " + code);
    }
}
